 '<h3 id="sdpa-cache-path">把同一个TinyDecoder接成缓存调用</h3>'+
 para('把前面的机制放回已学过的TinyDecoder：词表8项、位置表4项、664个参数。完整前缀路径一次处理[0,1,2,3]；缓存路径先处理[0,1]，再处理[2,3]。二者复用同一次SGD更新后的全部权重，只改变这次计算哪些位置、从哪里取得历史K/V。',
 '缓存保留上次的K/V张量。新输入先查词元表和位置表，再投影出自己的Q、K、V；新K/V接在历史后面，当前Q读合并后的合法前缀。注意力输出继续经过原来的残差、前馈和输出头，得到logits，即各候选词元的分数。缓存没有代替这些层。')+
 '<figure class="training-figure"><a href="diagrams/sdpa-cache-path.svg" target="_blank" rel="noopener"><img src="diagrams/sdpa-cache-path.svg" width="1024" height="530" alt="新输入2和3使用逻辑位置2和3，读取合并后的四位置KV；第一行能读前三项，第二行能读全部四项" loading="lazy"></a><figcaption>同一模型先缓存0、1，再续算2、3。矩阵的行是新query逻辑位置，列是缓存key逻辑位置；填色表示允许参与。</figcaption></figure>'+
 para('第二块的局部行号仍从0开始，实际query位置却是2、3。因此先加past_length=2，再判断key位置是否小于等于query位置：第一行允许0、1、2，第二行允许0、1、2、3。SDPA的布尔mask中True表示可见；把这个矩阵显式传入，is_causal保持False。')+
 trainingCode('缓存适配器的SDPA调用 · 节选，省略投影、拼接及后续层','PYTHON',`q_pos = past + torch.arange(length)
k_pos = torch.arange(k.shape[-2])
visible = k_pos[None, :] <= q_pos[:, None]
z = F.scaled_dot_product_attention(
    q, k, v, attn_mask=visible,
    is_causal=False, dropout_p=0.0,
)`)+
 para('选出一个词元后，把它作为下一次输入继续。提示[0,1]生成3项时，先prefill一次，再decode两次；缓存长度依次是2、3、4。最后选出的第3项尚未进入下一次前向，正好对应P+G−1=4。下面的原生实验把完整、单位置和两位置路径逐项接起来。');
 a.sections[6][1]+=
 '<details id="sdpa-cache-run"><summary>原生SDPA实验：同权重缓存、实际错误反例与生成轨迹</summary>'+
 para('tiny_decoder.py是原模型基础实验的逐字副本，其forward始终作为完整前缀参照。cache_lab.py继承相同层，先复现原来的两条输入和有效标签[1,3]的一次更新，再载入相同权重，新增缓存不增加参数。先预测两位置续算的可见矩阵，再运行。')+
 trainingCode('下载并完整解压sdpa-cache.zip，在目录中执行','SHELL',`python3.12 -m venv .venv
.venv/bin/pip install -r requirements.txt
.venv/bin/python -B cache_lab.py > local-record.json`)+
 table(['对照','本次实际结果','核对哪个接点'],[
  ['Attention章同一组三行Q/K/V','完整输出[[2,0],[0.5,3],[3.5,2]]；单query正确输出[3.5,2]','纸笔算例确实对应原生SDPA'],
  ['相同664参数模型，1+1+1+1 / 2+2 / 2+1+1','各路径全部logits最大误差≤'+Math.max(...Object.values(r.cases).map(v=>v.logits_max_error)).toExponential(3),'完整前缀参照不调用缓存适配器'],
  ['缓存路径故意改为is_causal=True','实际logits最大误差'+r.negative_is_causal.logits_max_error.toFixed(6)+'，输出断言拒绝','非方阵左上对齐会把当前位置当作局部第0行'],
  ['提示[0,1]，贪心选择3项','输出ID '+r.generation.generated_ids.join('、')+'；缓存2→3→4；每步logits与完整路径相符','生成后的词元何时真正写入KV'],
  ['强制CPU SDPBackend.MATH','实际profiler事件aten::_scaled_dot_product_attention_math','确认本次调用使用的实现路径，未作速度比较']
 ])+
 para('手算反例的第三个query本应读三项，结果为[3.5,2]；误设is_causal=True时原生API实际只允许第一项，返回[2,0]。模型负例也真的执行同一错误调用，再由原forward的完整前缀logits发现差异。结果记录区分实际使用的visible与应有的required_visible，便于从输出差异追回第一处错误坐标。',
 '本实验固定PyTorch 2.5.1、CPU float64和SDPBackend.MATH，只支持连续无padding前缀及原模型4个位置。它不执行GPU FlashAttention、分页调度、GQA或RoPE，也不评估极小模型的语言质量；生成ID仅用于核对执行状态。')+
 sourceAt('sdpa251API')+sourceAt('sdpa251Backend')+
 '<p><a href="labs/sdpa-cache.zip" download>下载完整原生SDPA实验包 ↓</a> · <a href="labs/sdpa-cache/README.md">运行说明</a> · <a href="labs/sdpa-cache/validation.json">本次结果与源码摘要</a></p>'+
 '<details class="full-code"><summary>完整cache_lab.py · 与下载源码逐字一致</summary>'+trainingCode('cache_lab.py','PYTHON',sdpaCacheFiles['cache_lab.py'])+'</details>'+
 '<details class="full-code"><summary>原TinyDecoder完整参照 · 与原模型基础源码逐字一致</summary>'+trainingCode('tiny_decoder.py','PYTHON',sdpaCacheFiles['tiny_decoder.py'])+'</details></details>';
 a.refs=[...new Set([...a.refs,'sdpa251API','sdpa251Backend'])];a.updated='2026.11.08';a.minutes=Math.max(a.minutes,30);
 const flash=articles.find(a=>a.id==='flash-attention-io');
