 mask[1]+=para('继续把同一位置规则落到框架：<a href="article/model-serving/#sdpa-cache-path">模型服务章用原664参数TinyDecoder接入真实SDPA缓存调用</a>，先按历史长度生成可见矩阵，再用完整前缀logits核对单位置与两位置续算。');
